from wsgiref.util import setup_testing_defaults

events = []
def app(environ, start_response):
    events.append('handler')
    raise ValueError('private diagnostic')

def error_boundary(inner):
    def wrapped(environ, start_response):
        try:
            return inner(environ, start_response)
        except Exception:
            start_response('500 Internal Server Error', [('Content-Type', 'text/plain')])
            return [b'Internal error']
    return wrapped

environ = {}
setup_testing_defaults(environ)
seen = []
def start(status, headers, exc_info=None):
    seen.append(status)
    return lambda chunk: None
body = b''.join(error_boundary(app)(environ, start))
assert events == ['handler']
assert seen == ['500 Internal Server Error']
assert body == b'Internal error'
assert b'private diagnostic' not in body
print(seen[0], body.decode())
